INSERT INTO public.facebook_posts (id, page_id, page_name, page_avatar, page_verified, page_followers, title, snippet, full_text, facebook_url, provider, provider_name, content_type, data_access_status, comment_count, reactions_count, shares_count, media_urls, tags, published_at, discovered_at)
VALUES
('fb-post-101', 'meta-dev-official', 'Meta for Developers', 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=100&auto=format&fit=crop&q=80', true, 3420000, 'Meta Connect 2026: Announcing Llama 4 Open Foundation Models', 'Today we are introducing Llama 4, our next generation multimodal intelligence foundation model trained openly on responsible high-throughput datasets...', 'Today we are introducing Llama 4, our next generation multimodal intelligence foundation model trained openly on responsible high-throughput datasets. Full weights and inference benchmarks available for research now. Over the past 12 months, our teams across FAIR and Infrastructure have pushed the boundary of multimodal reasoning, long-context latency, and energy efficiency.', 'https://www.facebook.com/MetaforDevelopers/posts/1016298491823901', 'meta_graph', 'Meta Graph API v21.0', 'post', 'public', 428, 8940, 1820, ARRAY['https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=800&auto=format&fit=crop&q=80'], ARRAY['AI', 'OpenSource', 'Llama4', 'MetaDevelopers'], '2026-11-21T14:32:00Z', NOW()),
('fb-post-102', 'nasa-official-page', 'NASA', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=100&auto=format&fit=crop&q=80', true, 28900000, 'NASA Artemis IV: Lunar Gateway Orbital Habitat Assembly Stream', 'Watch live as international partners test the habitation module dockings ahead of deep space exploration...', 'Watch live as international partners test the habitation module dockings ahead of deep space exploration. The crew module systems have completed their 72-hour autonomous stress sequence with zero delta anomalies. Humanity is preparing to establish a permanent sustainable presence on and around the Moon.', 'https://www.facebook.com/NASA/videos/892019284729102', 'apify', 'Apify Facebook Scraper', 'video', 'verified', 1640, 42100, 6890, ARRAY['https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&auto=format&fit=crop&q=80'], ARRAY['Artemis', 'NASA', 'LunarGateway', 'SpaceScience'], '2026-11-21T12:15:00Z', NOW()),
('fb-post-103', 'techcrunch-page', 'TechCrunch', 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=100&auto=format&fit=crop&q=80', true, 3100000, 'TechCrunch: Autonomous EV Battery Breakthrough Doubles Range in Winter Tests', 'Solid-state electrolyte cells designed by a Silicon Valley university spinout successfully withstood -30°C temperature cycles...', 'Solid-state electrolyte cells designed by a Silicon Valley university spinout successfully withstood -30°C temperature cycles while retaining 92% usable discharge capacity. Commercial production pilots slated for Q3.', 'https://www.facebook.com/TechCrunch/posts/94820194820192', 'rapidapi', 'RapidAPI Social Search', 'post', 'public', 312, 5210, 940, ARRAY['https://images.unsplash.com/photo-1558441719-79a099f6d4d7?w=800&auto=format&fit=crop&q=80'], ARRAY['ElectricVehicles', 'CleanTech', 'Hardware', 'BatteryTech'], '2026-11-21T09:40:00Z', NOW()),
('fb-post-104', 'natgeo-official', 'National Geographic', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=100&auto=format&fit=crop&q=80', true, 49500000, 'National Geographic: Marine Biologists Record Unprecedented Deep Coral Spawning', 'Filmed at a depth of 1,200 meters off the Galápagos rift using bioluminescence sensors...', 'Filmed at a depth of 1,200 meters off the Galápagos rift using bioluminescence sensors, this footage captures thousands of deep-water octocorals synchronized with geothermal vent cycles for the first time in recorded biology.', 'https://www.facebook.com/natgeo/videos/49201948291039', 'meta_graph', 'Meta Graph API v21.0', 'video', 'public', 890, 64200, 14500, ARRAY['https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800&auto=format&fit=crop&q=80'], ARRAY['Ocean', 'MarineLife', 'Conservation', 'Galapagos'], '2026-11-20T21:10:00Z', NOW())
INSERT INTO public.facebook_comments (id, post_id, post_title, author_name, author_avatar, text, published_at, likes_count, replies_count, sentiment, is_top_comment)
VALUES
('comm-101', 'fb-post-101', 'Meta Connect 2026: Announcing Llama 4 Open Foundation Models', 'Dr. Sarah Lin', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=100&auto=format&fit=crop&q=80', 'The quantization benchmark tables on edge Apple Silicon and RTX 5090 chips look remarkably competitive. Looking forward to testing native MoE routing efficiency in our robotics pipeline!', '2026-11-21T14:45:00Z', 64, 12, 'positive', true),
('comm-102', 'fb-post-101', 'Meta Connect 2026: Announcing Llama 4 Open Foundation Models', 'Alexandre Dumas', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&auto=format&fit=crop&q=80', 'Are the commercial license thresholds identical to Llama 3.3 for organizations exceeding 700M monthly active users?', '2026-11-21T15:02:00Z', 28, 4, 'neutral', false),
('comm-103', 'fb-post-102', 'NASA Artemis IV: Lunar Gateway Orbital Habitat Assembly Stream', 'Elena Rostova', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop&q=80', 'Watching this live feed from 380,000 kilometers away with crystal clarity is nothing short of awe-inspiring. Kudos to the optics and laser telemetry teams!', '2026-11-21T12:40:00Z', 142, 19, 'positive', true),
('comm-104', 'fb-post-103', 'TechCrunch: Autonomous EV Battery Breakthrough Doubles Range in Winter Tests', 'Marcus Bennett', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&auto=format&fit=crop&q=80', 'Laboratory scale solid state has promised this for five years. The critical bottleneck has always been dendrite prevention under fast DC charging rates above 350kW.', '2026-11-21T10:15:00Z', 89, 22, 'negative', false)
